export const PORTABLE_CATEGORY_MAP: Record<string, PortableCategory> = Object.fromEntries(
  PORTABLE_CATEGORIES.map((c) => [c.slug, c]),
);

export const PORTABLE_PRODUCT_MAP: Record<string, PortableProduct> = Object.fromEntries(
  PORTABLE_PRODUCTS.map((p) => [p.slug, p]),
);

export function productsInCategory(slug: string): PortableProduct[] {
  return PORTABLE_PRODUCTS.filter((p) => p.category === slug);
}
